// The sine and the cosine over one full turn. The two curves are a quarter of a
// period apart: the cosine is already at its maximum where the sine is still
// climbing through zero.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(340,260);
// The curve is sampled by an explicit path over radians, not by `import graph`:
// graph() plots (t, f(t)) for t in its own argument, and passing it degrees put
// the curve on a 0-360 x-axis while the axes are drawn over radians. The curve was
// then 50x wider than the axes, keepAspect fitted the picture to the curve, and the
// figure shipped as a letterbox sliver with the axes scaled to a few points tall.
real r(real d){return d*pi/180;}
path wave(real g(real x), real a, real b, int n) {
  path p;
  for (int i = 0; i <= n; ++i) p = p -- (a+(b-a)*i/n, g(a+(b-a)*i/n));
  return p;
}
draw((-0.7,-1.7)--(7.6,1.9),Arrow);
label("$x$",(7.6,1.9),SE);
draw((0,-1.7)--(0,1.9),Arrow);
label("$y$",(0,1.9),N);
draw(wave(new real(real x){return sin(r(x));},0,2*pi,360),red+1pt);
draw(wave(new real(real x){return cos(r(x));},0,2*pi,360),blue+1pt);
dot((pi/2,1),black+2.5pt);
dot((pi,0),black+2.5pt);
label("$90^\circ$",(pi/2,-1.45),S);
label("$180^\circ$",(pi,-1.45),S);
label("$\sin x$",(5.1,0.42),N);
label("$\cos x$",(2.35,-0.95),S);

// One and a half cycles of 3 sin(2(x - 30 degrees)) + 1, with the midline, the
// extreme values and the phase shift marked.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(360,240);
// The curve is sampled by an explicit path over radians, not by `import graph`:
// graph() plots (t, f(t)) for t in its own argument, and passing it degrees put
// the curve on a 0-360 x-axis while the axes are drawn over radians. The curve was
// then 50x wider than the axes, keepAspect fitted the picture to the curve, and the
// figure shipped as a letterbox sliver with the axes scaled to a few points tall.
real r(real d){return d*pi/180;}
real f(real x){return 3*sin(r(2*x-60))+1;}
path wave(real g(real x), real a, real b, int n) {
  path p;
  for (int i = 0; i <= n; ++i) p = p -- (a+(b-a)*i/n, g(a+(b-a)*i/n));
  return p;
}
draw((-0.5,-3.4)--(6.5,5.0),Arrow);
label("$x$",(6.5,5.0),SE);
draw((0,-3.4)--(0,5.0),Arrow);
label("$y$",(0,5.0),N);
draw((0,1)--(6.4,1),dashed);
label("$y=1$",(0.15,1.3),NW);
draw(wave(f,0,r(200),200),red+1pt);
dot((r(30),1),black+2.5pt);
dot((r(75),4),black+2.5pt);
dot((r(165),-2),black+2.5pt);
label("$30^\circ$",(r(30),-3.2),S);
label("$75^\circ$",(r(75),-3.2),S);
label("$165^\circ$",(r(165),-3.2),S);
label("$4$",(r(75),4),NE);
label("$-2$",(r(165),-2),SE);

// The tangent between its asymptotes. Every branch is strictly increasing and
// runs from minus infinity to plus infinity across the interval it owns.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,260);
// The curve is sampled by an explicit path over radians, not by `import graph`:
// graph() plots (t, f(t)) for t in its own argument, and passing it degrees put
// the curve on a 0-360 x-axis while the axes are drawn over radians. The curve was
// then 50x wider than the axes, keepAspect fitted the picture to the curve, and the
// figure shipped as a letterbox sliver with the axes scaled to a few points tall.
// x is in radians throughout, matching the dashed asymptotes at 90 and 270 degrees and
// the marked zero at 180, so tan takes radians too and each branch is walked outwards
// from its zero only while the ordinate is inside the frame: sampling up to a pole puts
// an unbounded ordinate in the bounding box and collapses the figure again.
real r(real d){return d*pi/180;}
real f(real x){return 3*tan(x);}
path half(real x0, real dir, int n, real ymax) {
  path p = (x0, f(x0));
  for (int i = 1; i <= n; ++i) {
    real x = x0 + dir*2*pi*i/(4*n);
    if (abs(f(x)) > ymax) break;
    p = p -- (x, f(x));
  }
  return p;
}
draw((-0.5,-6.0)--(7.3,6.0),Arrow);
label("$x$",(7.3,6.0),SE);
draw((0,-6.0)--(0,6.0),Arrow);
label("$y$",(0,6.0),N);
draw((r(90),-6.0)--(r(90),6.0),dashed);
draw((r(270),-6.0)--(r(270),6.0),dashed);
draw(half(0,+1,180,6.0),red+1pt);
draw(half(0,-1,180,6.0),red+1pt);
draw(half(pi,+1,180,6.0),red+1pt);
draw(half(pi,-1,180,6.0),red+1pt);
dot((r(180),0),black+2.5pt);
label("$90^\circ$",(r(90),5.7),N);
label("$180^\circ$",(r(180),-5.7),S);
label("$270^\circ$",(r(270),5.7),N);
label("$y=\tan x$",(r(240),3.9),NW);
